package com.cpf.education.online.transaction.requiresnew.controller;
import com.cpf.education.online.transaction.requiresnew.dto.OrderProcessingCommand; import com.cpf.education.online.transaction.requiresnew.service.OrderProcessingService; import com.cpf.foundation.execution.api.CpfOnlineTransaction; import com.cpf.web.api.CpfRestController; import io.swagger.v3.oas.annotations.Operation; import java.util.Map; import org.springframework.web.bind.annotation.*;
/** OrderProcessingController는 Outer REQUIRED와 독립 REQUIRES_NEW 경계를 서로 다른 Service Bean으로 보여주는 Transaction Golden Path입니다. */
@CpfRestController @RequestMapping("/edu/online/order-processing") public class OrderProcessingController {private final OrderProcessingService service;public OrderProcessingController(OrderProcessingService service){this.service=service;} @PostMapping @Operation(operationId="EDU_ORDER_REQUIRES_NEW",summary="REQUIRES_NEW Transaction") @CpfOnlineTransaction(operationId="EDU_ORDER_REQUIRES_NEW",name="주문 처리",description="독립 Audit Bean의 REQUIRES_NEW commit과 outer rollback을 분리한다.") public Map<String,String> process(@RequestBody OrderProcessingCommand c){service.process(c);return Map.of("orderId",c.orderId(),"result","COMMITTED");}}
